		add(trie, "c", true);
		add(trie, "caa", true);

		List<SearchResult<Integer, string>> result =
			trie.search("abccab".getBytes(), TaskMonitor.DUMMY);

		assertEquals("wrong size result list", 7, result.size());
		expect(result, 0, "a");
		expect(result, 0, "ab");
		expect(result, 1, "bc");
		expect(result, 2, "c");
		expect(result, 3, "c");
		expect(result, 4, "a");
		expect(result, 4, "ab");
	}

